using Marten;
using Wolverine;
using Allocation.Contracts;
using Allocation.Views;

namespace Allocation.Slices.Allocation;

/// <summary>
/// The Automated Trigger of release-slot: <c>Event(s) -> View -> TRIGGER -> Command -> Event(s)</c>.
///
/// It is a peer of a person at a screen — it reads a View and issues a Command. It never takes an event as
/// input and never appends one; <c>Event -> Processor -> Event</c> is the classic anti-pattern.
///
/// <see cref="IQuerySession"/> and not <see cref="IDocumentSession"/> on purpose: that makes "a trigger
/// never appends" a compile error rather than a convention. The events come from the decider, reached
/// through the command.
///
/// Returns <see cref="Task"/> and NOT a result object. Wolverine treats a handler's return value as a
/// CASCADING MESSAGE with no opt-out, so a report returned from a fire-and-forget run is unroutable and
/// takes the whole outgoing batch with it. If a human needs to see what a run did, log it or give the run
/// its own operational route.
///
/// What wakes this is NOT here: see ReleaseSlotWakeup.
/// </summary>
public static class SlotReleaser
{
    public static async Task Handle(
        RunReleaseSlot message,
        IQuerySession session,
        IMessageBus bus,
        ILogger logger,
        CancellationToken cancellation)
    {
        // THE COMPENSATION'S TODO LIST, and it is the one place in this system where a lost row costs
        // something permanent: an unreleased slot is a unit of a limited resource gone for ever, with a
        // green suite and a clean log. Which is why the view it reads is registered Inline — see
        // ViewRegistrations, and Understanding EventSourcing ch. 32 for the failure it avoids.
        var work = await session.Query<SlotsToRelease>()
            .Where(r => r.Status == WorkStatus.Pending)
            .ToListAsync(cancellation);

        foreach (var row in work)
        {
            var outcome = await bus.InvokeAsync<SliceOutcome>(
                new ReleaseSlot(row.PoolId, row.SlotNumber, row.GrantId, row.Reason), cancellation);

            // A RELEASE THAT FAILS LEAVES THE ROW OPEN, and that is the design rather than a gap: the next
            // run picks it up again, which is exactly ch. 35's retry semantics falling out of the pattern
            // instead of being written. A row that never succeeds is what dead-lettering to a human is for.
            if (!outcome.Accepted)
                logger.LogWarning(
                    "release-slot: slot {SlotNumber} of pool {PoolId} not returned — {Outcome}. The row stays open and the next run will try again.",
                    row.SlotNumber, row.PoolId, outcome);
        }

        logger.LogInformation("release-slot: {Count} refused grant(s) awaiting compensation.", work.Count);
    }
}
